from pathlib import Path
root=Path('/tmp/run35113794298-artifacts')
for p in root.rglob('check-outcomes.json'):
  print('ROOT',p.parent)
  print(json.dumps(json.loads(p.read_text()), indent=2))
  for n in ('representative-engine.json','representative-engine-diagnostics.json','product-doctor.json','reproducibility.json','ocr-asset-context.json','required-doctor.json','networkless-doctor.json','runtime-manifest.json','runtime-manifest-clean.json','runtime-sbom.json','runtime-sbom-clean.json','artifact-identity.json','artifact-identity-clean.json','heavy-evidence-status.json'):
