   elif n in ('required-doctor.json','networkless-doctor.json'): print(n,'overall=',d.get('overall'),'checks=',[(x.get('label'),x.get('status')) for x in d.get('checks',[]) if x.get('label') in ('LibreOffice PPTX roundtrip','Paddle OCR roundtrip','Paddle load','OCR asset identity')])
   elif n=='heavy-evidence-status.json': print(n,d)
   elif n.startswith('runtime-manifest'): print(n,'image=',d.get('image'),'ocr=',d.get('ocr_assets',{}).get('model_identity'))
   elif n.startswith('artifact-identity'): print(n,d)
